<script>
import Layout from "@/router/layouts/main";
import appConfig from "@/app.config";
import locationLogs from "./locationLogs/index.vue";
import custodyTransferLogs from "./custodyTransferLogs/index.vue";
export default {
  page: {
    meta: [
      {
        name: "description",
        content: appConfig.description,
      },
    ],
  },
  components: {
    Layout,
    locationLogs,
    custodyTransferLogs
  },
  data() {
    return {
      fixed_asset_product:{}
    };
  },
  methods: {
    getFixedAsseById(id){
      this.http.get('fixed-assets/fixed-asset-product/'+id).then((res)=>{
        if(res.status)
        this.fixed_asset_product=res.data
      })

    }
  },
  created() { 
    this.getFixedAsseById(this.$route.params.fixed_asset_product_id)
  },
};
</script>

