          <div class="mx-2">\</div>
          <div>
            <router-link :to="{name:'fixed-assets-profile', params:{id:this.$route.params.id} }" class="click " >

            <h5 class="m-0">{{
              $i18n.locale == "ar"
                ? fixed_asset_product?.fixed_asset?.name
