      </b-tab>
      <b-tab>
        <template v-slot:title>
          <span :dir="$i18n.locale == 'ar' ? 'rtl' : 'ltr'" class="d-none d-sm-inline-block">{{
            $t("fixed_assets.location_logs") }}</span>
